-- DQ-002: Sample Identifier Integrity---- Purpose:-- Validate the integrity of the technical sample identifier-- generated during the ingestion process.---- Expected result:-- - minimum sample_id = 1-- - maximum sample_id = 705-- - distinct sample_id count = 705-- - total record count = 705---- This validation does not modify the data.SELECT    MIN(sample_id) AS min_sample_id,    MAX(sample_id) AS max_sample_id,    COUNT(DISTINCT sample_id) AS distinct_sample_ids,    COUNT(*) AS total_recordsFROM staging.brca_sample_wide;